        "id": "azhe_04",
        "title": "第四幕 · 没有名字的曲子",
        "sub": false,
        "need": {
          "bond": 50,
          "score": 0,
          "flags": []
        },
        "lines": [
          {
            "who": "narrator",
            "text": "深夜的排练室，你听见一段没听过的旋律。阿喆一个人坐在角落练琴，没有谱，闭着眼。琴声的脾气很奇怪——前半段像在问一个问题，后半段像在等一个回答。"
          }
        ],
        "choices": [
          {
            "text": "（安静地听完，等他睁眼）",
            "bond": 5,
            "score": 0,
            "flags": [],
            "next": "azhe_04b"
          },
          {
            "text": "「这首叫什么？」",
            "bond": 2,
            "score": 0,
            "flags": [],
            "next": "azhe_04c"
          },
          {
            "text": "（不打扰，悄悄离开）",
            "bond": 0,
            "score": 0,
            "flags": [],
            "next": null
          }
        ],
        "asset": "personal_azhe_04",
