        "lines": [
          {
            "who": "azhe",
            "text": "他睁开眼，看到你，并不意外，像等了很久。「……你听到了啊。」他低头拨了一个音，「这首曲子，我写了三年。一直没敢给别人听。」他抬眼看你，「你是第一个。」"
          }
        ],
