            "text": "「好了好了，都少说两句。」大鹅抱着琴走过来，笑着打圆场，「十元的音是不稳，可她拉来的场子、聚起来的人，哪个不稳？排练继续，这段我陪她过。」 风波暂时压了下去。但你看懂了——大鹅的和稀泥里，藏着一种小心翼翼的维护。散场后，他独自在角落里调琴，琴箱上放着十元落下的发圈。",
