            "who": "narrator",
            "text": "声明发出去，评论区吵得更凶了——但乐手们一个接一个地转发。小塔：「鼓手小塔，实名。」冰冰：「大提冰冰，实名。」阿喆转了你的声明，配字：「水果是我洗的，话是真的。」"
