        "lines": [
          {
            "who": "narrator",
            "text": "音乐节的人潮里，她拉着你的袖子穿梭在摊位之间，笑得比舞台灯还亮。压轴乐队响起的时候，你们站在很远的外围，她听了一会儿，忽然靠过来，把半张脸埋在你的肩膀里。"
          },
          {
            "who": "player",
            "text": "「困了？」你问。"
          },
          {
            "who": "shiyuan",
            "text": "她摇摇头，声音闷闷的：「没有。就是想靠一下。」"
          },
          {
            "who": "narrator",
            "text": "那首歌唱了七分钟，她靠了七分钟。散场的人流里，谁都没有先动。"
          }
        ],
