        "lines": [
          {
            "who": "shiyuan",
            "text": "宝石突然从门后探出半个脑袋围观。十元头也不抬：「宝石，V 我 50——帮我占卜一下考试运。」"
          },
          {
            "who": "baoshi",
            "text": "宝石盯着自己的手机看了三秒，肉痛地转了 25 块：「……V 你 25。铁公鸡，也要讲基本法。」"
          },
          {
            "who": "shiyuan",
            "text": "钱还没捂热，他转身就跑，跑之前还顺走了你的半包饼干。十元对着他的背影喊：「25 的卦象也算数吗！」"
          }
        ],
