            "text": "星海复习期间，一个演出上认识的制作人找上了你。他想做一家「乐手经纪＋演出策划」工作室，开口第一句话就是：「你有乐团的资源和人脉，我有渠道。合伙干不干？」\n\n工作室的执照、场地方案、第一年的企划书，就摆在你面前。你知道接下它意味着什么——白天跑场地、谈合作、写方案；而晚上，还有一个人的乐理题在等你。\n\n你也知道，做得好，它能给某个考进星海的人，铺一条回深圳的路。",
