        "lines": [
          {
            "who": "narrator",
            "text": "散场后，你在后台堵住了雪子。他抱着键盘，长发扎成一束，见你来也不意外。"
          },
          {
            "who": "player",
            "text": "你决定贴脸开大：「你是不是喜欢宝石。」"
          },
          {
            "who": "xuezi",
            "text": "（他想都没想：）「谁不喜欢宝石呢？」"
          },
          {
            "who": "player",
            "text": "「呵呵……」你冷笑了一声，没接话。"
          },
          {
            "who": "xuezi",
            "text": "（他沉默了几秒，忽然笑了，看着远处正在收拾话筒的宝石：）「一开始，是有点吧。」他把键盘包背好，语气轻下来，「但是后来我想明白了——太阳照到你，不是真的为你一个人发光。我恰好路过，晒到了，仅此而已。」"
          },
          {
            "who": "xuezi",
            "text": "（他转过头看你，眼睛很亮：）「宝石……他不明白这些。所以，别让他输。」"
          }
        ],
